import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

import { storage } from '../storage/storage';

/**
 * Sound effects + music. Files are generated by `npm run sounds`
 * (scripts/generate-sounds.js) — swap any file in assets/sounds to re-skin.
 */
const SOURCES = {
  drop: require('../../assets/sounds/drop.wav'),
  click: require('../../assets/sounds/click.wav'),
  combo: require('../../assets/sounds/combo.wav'),
  powerup: require('../../assets/sounds/powerup.wav'),
  vanish: require('../../assets/sounds/vanish.wav'),
  gameover: require('../../assets/sounds/gameover.wav'),
};

const MERGE_SOURCES = [
  require('../../assets/sounds/merge_00.wav'),
  require('../../assets/sounds/merge_01.wav'),
  require('../../assets/sounds/merge_02.wav'),
  require('../../assets/sounds/merge_03.wav'),
  require('../../assets/sounds/merge_04.wav'),
  require('../../assets/sounds/merge_05.wav'),
  require('../../assets/sounds/merge_06.wav'),
  require('../../assets/sounds/merge_07.wav'),
  require('../../assets/sounds/merge_08.wav'),
  require('../../assets/sounds/merge_09.wav'),
  require('../../assets/sounds/merge_10.wav'),
];

type Sfx = keyof typeof SOURCES;

/** Small round-robin pool per sound so rapid repeats overlap instead of cutting off. */
class Voice {
  private players: AudioPlayer[] = [];
  private i = 0;
  constructor(
    private source: number,
    private size: number,
    private volume: number,
  ) {}
  play() {
    if (this.players.length < this.size) {
      const p = createAudioPlayer(this.source);
      p.volume = this.volume;
      this.players.push(p);
    }
    const p = this.players[this.i++ % this.players.length];
    p.seekTo(0).catch(() => {});
    p.play();
  }
  release() {
    this.players.forEach((p) => p.remove());
    this.players = [];
  }
}

let sfxOn = storage.getSettings().sfx;
let musicOn = storage.getSettings().music;
let music: AudioPlayer | null = null;
let musicWanted = false;
const voices = new Map<string, Voice>();

function voice(key: string, source: number, size: number, volume: number) {
  let v = voices.get(key);
  if (!v) voices.set(key, (v = new Voice(source, size, volume)));
  return v;
}

export const sound = {
  async init() {
    try {
      await setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers', shouldPlayInBackground: false });
    } catch {}
  },

  play(name: Sfx) {
    if (!sfxOn) return;
    try {
      voice(name, SOURCES[name], name === 'drop' || name === 'click' ? 3 : 2, name === 'gameover' ? 0.8 : 0.7).play();
    } catch {}
  },

  merge(level: number) {
    if (!sfxOn) return;
    try {
      voice(`merge${level}`, MERGE_SOURCES[Math.min(level, MERGE_SOURCES.length - 1)], 2, 0.75).play();
    } catch {}
  },

  /** Start/stop the background loop (respects the music setting). */
  setMusicPlaying(want: boolean) {
    musicWanted = want;
    try {
      if (want && musicOn) {
        if (!music) {
          music = createAudioPlayer(require('../../assets/sounds/music_loop.wav'));
          music.loop = true;
          music.volume = 0.35;
        }
        music.play();
      } else music?.pause();
    } catch {}
  },

  setSfxEnabled(v: boolean) {
    sfxOn = v;
  },
  setMusicEnabled(v: boolean) {
    musicOn = v;
    sound.setMusicPlaying(musicWanted);
  },
};
